/**
 * Title, description and actions at the top of a working page (`design/components/page-header.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/page-header.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { Component, ViewEncapsulation, input } from '@angular/core'

import { MEMBER_PROVIDERS, SlotOutlet, SlotTemplate, useMember } from '@polymorph/angular'
import styles from '@polymorph/recipes/structure/page-header.module.css'
import { Inline, type InlineProps } from '../layout/Inline'

/** Title, description and actions at the top of a working page: the inputs it takes, by the React member's prop names. */
export interface PageHeaderProps {
  description?: string
  title: string
}

/** Title, description and actions at the top of a working page. */
@Component({
  selector: 'pm-page-header',
  encapsulation: ViewEncapsulation.None,
  host: { style: 'display: contents' },
  providers: [...MEMBER_PROVIDERS],
  imports: [SlotOutlet, SlotTemplate, Inline],
  // prettier-ignore
  template: `<ng-template pmSlot="actions" [pmSlotOf]="$"><ng-content select="[slot=actions]" /></ng-template>
<ng-template pmSlot="titleEdit" [pmSlotOf]="$"><ng-content select="[slot=titleEdit]" /></ng-template>
<header
[attr.class]="e1()"
data-member="page-header"
><!-- text -->
<div
[attr.class]="e2()"
>@if (e3()) {<!-- titleRow -->
<div
[attr.class]="e4()"
><!-- title -->
<h1
[attr.class]="e5()"
>{{ e6() }}</h1>
<!-- titleEdit -->
<div
[attr.class]="e7()"
><ng-container [pmSlotOutlet]="'titleEdit'" [pmSlotOf]="$" /></div></div>} @else {<!-- title -->
<h1
[attr.class]="e8()"
>{{ e9() }}</h1>}
@if (e10()) {<!-- description -->
<p
[attr.class]="e11()"
>{{ e12() }}</p>}</div>
@if (e13()) {<pm-inline
[gap]="e14()"
[wrap]="e15()"
><ng-container [pmSlotOutlet]="'actions'" [pmSlotOf]="$" pmSlotInto="default" /></pm-inline>}</header>`,
})
export class PageHeader {
  readonly description = input<PageHeaderProps['description']>(undefined)
  readonly title = input.required<PageHeaderProps['title']>()
  protected readonly $ = useMember({
    events: [],
    props: { description: () => this.description(), title: () => this.title() },
  })
  protected readonly $p = this.$.props

  constructor() {
    this.$.pass('titleEdit', () => ({ valueHidden: true }))
  }

  protected e1() {
    return styles.header
  }

  protected e2() {
    return styles.text
  }

  protected e3() {
    return this.$.filled('titleEdit')
  }

  protected e4() {
    if (!this.$.filled('titleEdit')) return undefined as never
    return styles.titleRow
  }

  protected e5() {
    if (!this.$.filled('titleEdit')) return undefined as never
    return styles.title
  }

  protected e6() {
    if (!this.$.filled('titleEdit')) return undefined as never
    return this.$p.title
  }

  protected e7() {
    if (!this.$.filled('titleEdit')) return undefined as never
    return styles.titleEdit
  }

  protected e8() {
    if (this.$.filled('titleEdit')) return undefined as never
    return styles.title
  }

  protected e9() {
    if (this.$.filled('titleEdit')) return undefined as never
    return this.$p.title
  }

  protected e10() {
    return this.$p.description !== undefined
  }

  protected e11() {
    if (!(this.$p.description !== undefined)) return undefined as never
    return styles.description
  }

  protected e12() {
    if (!(this.$p.description !== undefined)) return undefined as never
    return this.$p.description
  }

  protected e13() {
    return this.$.filled('actions')
  }

  protected e14(): InlineProps['gap'] {
    if (!this.$.filled('actions')) return undefined as never
    return 3
  }

  protected e15(): InlineProps['wrap'] {
    if (!this.$.filled('actions')) return undefined as never
    return true
  }
}
